public class RegistryWrapper<T> {
	private final Registry<T> registry;
	private final Map<ResourceLocation, T> runtimeObjects;

	public RegistryWrapper(Registry<T> registry) {
		this.registry = registry;
		this.runtimeObjects = new HashMap<>();
	}

	public T get(ResourceLocation id) {
		return registry.get(id);
	}

	public void register(ResourceLocation id, T object) {
		registry.register(id, object);
	}

	public <B extends BuilderBase<T>> B create(ResourceLocation id, Class<B> builderClass) {
		try {
			var constructor = builderClass.getConstructor(ResourceLocation.class);
			return constructor.newInstance(id);
		} catch (Exception e) {
			throw new KubeRuntimeException("Failed to create builder: " + builderClass.getName(), e);
		}
	}

	public Stream<T> getAll() {
		return registry.entrySet().stream().map(Holder::value);
	}

	public Set<ResourceLocation> keys() {
		return registry.keySet();
	}
}
